import React from 'react';

const App = () => {
  return (
    <div className="lp-container">
      {/* 1. インラインCSS: 特殊なフォント縁取りと集中線を定義 */}
      <style dangerouslySetInnerHTML={{ __html: `
        @import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=Noto+Sans+JP:wght@900&display=swap');

        .lp-container {
          background-color: #000;
          color: #fff;
          font-family: 'Noto Sans JP', sans-serif;
          overflow-x: hidden;
        }

        /* 爆発的な縁取り文字 */
        .mega-title {
          font-size: clamp(3rem, 10vw, 8rem);
          font-weight: 900;
          color: #ffde00;
          text-transform: uppercase;
          line-height: 0.9;
          filter: drop-shadow(5px 5px 0px #ff0000);
          -webkit-text-stroke: 2px #000;
          paint-order: stroke fill;
        }

        /* アメコミ風の集中線背景 */
        .action-bg {
          background: 
            radial-gradient(circle, transparent 20%, #000 80%),
            repeating-conic-gradient(from 0deg, #333 0deg 10deg, transparent 10deg 20deg);
          position: absolute;
          inset: 0;
          opacity: 0.3;
          z-index: 0;
        }

        /* 斜めカットのセクション */
        .skew-section {
          transform: skewY(-5deg);
          margin-top: -50px;
          border-top: 10px solid #000;
          border-bottom: 10px solid #000;
        }
        .skew-content {
          transform: skewY(5deg);
        }

        /* 強烈な影 */
        .hard-shadow {
          box-shadow: 12px 12px 0px 0px #000;
        }

        /* ボタンの震動アニメーション */
        @keyframes rumble {
          0% { transform: translate(0,0) rotate(-2deg) scale(1); }
          50% { transform: translate(2px, 2px) rotate(-2deg) scale(1.02); }
          100% { transform: translate(0,0) rotate(-2deg) scale(1); }
        }
        .animate-rumble {
          animation: rumble 0.2s infinite;
        }
      `}} />

      {/* HERO SECTION */}
      <section className="relative min-h-screen flex flex-col items-center justify-center pt-20 pb-32 overflow-hidden bg-red-600">
        <div className="action-bg"></div>

        <div className="relative z-10 container mx-auto px-4 text-center">
          <div className="inline-block bg-black text-white px-6 py-2 mb-4 font-black text-2xl transform -rotate-3 italic">
            WEEKLY JUMP RANKING APP
          </div>

          <h1 className="mega-title italic mb-8 transform -rotate-2">
            ジャンプ順位<br/>
            <span className="text-white">WEBアプリ</span><br/>
            登場!!!
          </h1>

          <div className="max-w-2xl mx-auto bg-yellow-400 text-black p-6 border-8 border-black font-black text-2xl md:text-4xl shadow-[10px_10px_0_0_#fff] transform rotate-1">
             毎週の掲載順位を<br className="md:hidden"/>
             光速でチェックせよ！
          </div>
        </div>
      </section>

      {/* FEATURES SECTION */}
      <section className="skew-section bg-blue-700 py-24 relative z-20">
        <div className="skew-content container mx-auto px-4">
          <div className="grid md:grid-cols-2 gap-12 items-center">

            {/* 特徴リスト */}
            <div className="space-y-8">
              <div className="bg-white text-black p-8 border-8 border-black hard-shadow transform -rotate-2">
                <h3 className="text-4xl font-black mb-2 italic text-red-600">01. 爆速更新</h3>
                <p className="text-xl font-bold">最新の順位をどこよりも早くお届け。発売日の興奮をそのままに！</p>
              </div>

              <div className="bg-yellow-400 text-black p-8 border-8 border-black hard-shadow transform rotate-1">
                <h3 className="text-4xl font-black mb-2 italic text-blue-800">02. 徹底分析</h3>
                <p className="text-xl font-bold">過去の推移をグラフ化。推し作品の「生き残り」をデータで支援！</p>
              </div>

              <div className="bg-red-500 text-white p-8 border-8 border-black hard-shadow transform -rotate-1">
                <h3 className="text-4xl font-black mb-2 italic text-yellow-300">03. 推し通知</h3>
                <p className="text-xl font-bold">お気に入り作品の順位変動を見逃すな。スマホに熱狂をダイレクト送信！</p>
              </div>
            </div>

            {/* スマホ画面風UI */}
            <div className="relative flex justify-center">
              <div className="w-[340px] h-[680px] bg-black rounded-[3rem] p-4 border-4 border-gray-700 shadow-[20px_20px_0_0_#ffde00]">
                <div className="bg-gray-100 h-full w-full rounded-[2.5rem] overflow-hidden flex flex-col">
                  <div className="bg-red-600 text-white pt-10 pb-4 text-center font-black italic text-xl border-b-4 border-black">
                    JUMP RANKING
                  </div>
                  <div className="flex-grow p-4 overflow-y-auto">
                    {[
                      {r: 1, t: "ONE PIECE", c: "▲ 0", cl: "text-gray-500"},
                      {r: 2, t: "SAKAMOTO DAYS", c: "▲ 2", cl: "text-green-600"},
                      {r: 3, t: "アオのハコ", c: "▲ 1", cl: "text-green-600"},
                      {r: 4, t: "カグラバチ", c: "▼ 2", cl: "text-red-600"},
                    ].map((item, i) => (
                      <div key={i} className="bg-white border-4 border-black p-3 mb-3 flex items-center shadow-[4px_4px_0_0_#ccc]">
                        <span className="text-3xl font-black italic mr-4 text-red-600">{item.r}</span>
                        <span className="font-black flex-grow truncate">{item.t}</span>
                        <span className={`font-black ${item.cl}`}>{item.c}</span>
                      </div>
                    ))}
                    {/* ダミーグラフ */}
                    <div className="mt-4 p-4 bg-white border-4 border-black">
                      <div className="h-24 w-full flex items-end gap-2 px-2 border-b-4 border-black">
                        {[40, 80, 50, 90, 70, 100].map((h, i) => (
                          <div key={i} style={{height: `${h}%`}} className="flex-grow bg-blue-600"></div>
                        ))}
                      </div>
                      <p className="text-center font-black text-xs mt-2 italic">RANKING TREND</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

          </div>
        </div>
      </section>

      {/* CTA SECTION */}
      <section className="py-32 bg-yellow-400 relative overflow-hidden flex flex-col items-center">
        <div className="action-bg" style={{opacity: 0.1}}></div>
        <h2 className="text-black text-5xl md:text-7xl font-black italic mb-12 relative z-10 transform -rotate-2">
          今すぐアクセスせよ!!
        </h2>
        <div className="relative z-10 bg-white border-[10px] border-black p-6 md:p-10 shadow-[15px_15px_0_0_#000] flex flex-col md:flex-row items-center gap-6 animate-rumble">
          <span className="text-black font-black text-4xl md:text-6xl tracking-tighter">jump-web.app</span>
          <button className="bg-red-600 text-white text-3xl font-black px-10 py-4 border-4 border-black hover:bg-black transition-colors">
            GO! 🔍
          </button>
        </div>
      </section>

      <footer className="bg-black py-10 text-center text-gray-500 font-bold italic">
        <p>© 2026 JUMP RANKING FAN PROJECT</p>
      </footer>
    </div>
  );
};

export default App;
